import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine } from '../src/invoices.js';

test('createInvoice creates a valid invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[0].name, 'Development (hour)');
  assert.equal(result.value.lines[0].qty, 10);
  assert.equal(result.value.lines[0].unitPrice, 9500);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(result.value.lines[1].name, 'Logo package');
  assert.equal(result.value.lines[1].qty, 1);
  assert.equal(result.value.lines[1].unitPrice, 120000);
  assert.equal(result.value.lines[1].vatRate, 21);
});

test('createInvoice handles CUSTOMER_NOT_FOUND', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('createInvoice handles DATE_INVALID for wrong format', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '10-07-2026',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice handles DATE_INVALID for non-existent date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-30',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice handles DATE_INVALID for missing parts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice handles NO_LINES for empty array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice handles NO_LINES for undefined', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: undefined,
  });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice handles QTY_INVALID for zero', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 0 }],
  });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice handles QTY_INVALID for negative', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: -5 }],
  });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice handles QTY_INVALID for fractional', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 2.5 }],
  });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice handles UNKNOWN_SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'UNKNOWN', qty: 1 }],
  });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice does not mutate input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  };
  const inputCopy = JSON.parse(JSON.stringify(input));
  createInvoice(input);
  assert.deepEqual(input, inputCopy);
});

test('createInvoice handles multiple lines with mixed validity (stops at first error)', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'INVALID', qty: 1 },
    ],
  });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice with products having different VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 2 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].vatRate, 9);
  assert.equal(result.value.lines[2].vatRate, 0);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { qty: 10, unitPrice: 9500 };
  assert.equal(lineTotal(line), 95000);
});

test('lineTotal with qty of 1', () => {
  const line = { qty: 1, unitPrice: 120000 };
  assert.equal(lineTotal(line), 120000);
});

test('lineTotal with qty of 0', () => {
  const line = { qty: 0, unitPrice: 9500 };
  assert.equal(lineTotal(line), 0);
});

test('lineTotal with large quantities', () => {
  const line = { qty: 1000, unitPrice: 5000 };
  assert.equal(lineTotal(line), 5000000);
});

test('invoiceTotals calculates subtotal and total for single line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.deepEqual(totals, {
    subtotal: 47500, // 5 * 9500
    total: 47500,
  });
});

test('invoiceTotals calculates subtotal and total for multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.deepEqual(totals, {
    subtotal: 95000 + 120000, // 215000
    total: 95000 + 120000,
  });
});

test('invoiceTotals with multiple lines of different products', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // 10 * 9500 + 1 * 120000 + 100 * 37 = 95000 + 120000 + 3700 = 218700
  assert.deepEqual(totals, {
    subtotal: 218700,
    total: 218700,
  });
});

test('invoiceTotals with many lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'DEV-HOUR', qty: 12 },
      { sku: 'COPY-HOUR', qty: 4 },
      { sku: 'SUPPORT-HOUR', qty: 6 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // 8 * 8500 + 12 * 9500 + 4 * 6000 + 6 * 7250
  // = 68000 + 114000 + 24000 + 43500 = 249500
  assert.deepEqual(totals, {
    subtotal: 249500,
    total: 249500,
  });
});
